    var q = (rule && rule.query) || {};
    if (!q.mutex) return 0; // rule opted out of the mutex — not ours to add
    try {
        var list = mcpParse(github_list_prs({
            workspace: repoInfo.owner, repository: repoInfo.repo, state: 'open'
