       }));
       sm.action({ jobParams: { owner: 'a', repo: 'b', machineAuthor: 'ai-teammate', rules: [RULES.fail] } });

       assert.equal(sm.capturedPrComments.length, 1);
       // 2026-10-04: no linked issue → the rework leg arms PR-ANCHORED
