        var otherHolder = 0;
        for (var i = 0; i < arr.length; i++) {
            var p = arr[i];
            var num = (p && (p.number || p.prNumber)) || 0;
            var labels = ((p && p.labels) || []).map(function (l) {
                return (l && l.name) || l;
            });
