// no-records fail-open behavior.
function verdictMachineLogins(effectiveConfig) {
    return machineAuthorModule.machineAuthorLogins(
        machineAuthorModule.resolveMachineAuthor(RUN_JOB_PARAMS, effectiveConfig));
}

