                pr: { number: 1211, labels: ['pr_approved', 'ai_validating'], body: 'no closing keyword' },
                prComments: [
                    { body: redMarker('dead1211aa', 1, 3) },
                    { body: redMarker('dead1211aa', 2, 3) },
