                ]
            }
        }));
        sm.action({ jobParams: { owner: 'a', repo: 'b', machineAuthor: 'ai-teammate',
            rules: [RULES.fail] } });

        assert.ok(!sm.capturedPrLabelAdds.some(function (a) {
