                    return [prItem(1194, { labels: ['pr_approved', 'ai_validating'],
                        author: 'ai-teammate', headSha: 'dead1194aa', branch: 'ai/gh-1194' })];
                }
                return [prItem(1215, { labels: ['pr_approved'], branch: 'feat/1215',
                    headSha: 'dead1215aa', author: 'ai-teammate' })];
