                pr: { number: 1211, labels: ['pr_approved', 'ai_validating'], body: 'Fixes #1210' },
                // Previous red was ALSO on shaX — the lap in between moved nothing.
                prComments: [{ body: redMarker('dead1211aa', 1, 3) }]
