              conclusion: 'failure', created_at: '2026-10-10T03:00:00Z' },
            { id: 2, event: 'workflow_dispatch', head_sha: 'shaX', status: 'in_progress',
              conclusion: null, created_at: '2026-10-10T02:00:00Z' },
