                { number: 1215, labels: [{ name: 'pr_approved' }], head: { sha: 'dead1215aa' } }
            ],
            prComments: []
        }
    }));
    sm.action({ jobParams: { owner: 'a', repo: 'b', machineAuthor: 'ai-teammate',
        rules: [RULES.fail, RULES.validate] } });

