        assert.ok(sm.capturedPrComments[0].body.indexOf('human owns this PR') !== -1,
            'ownership is handed to a human explicitly');
        assert.ok(sm.capturedPrComments[0].body.indexOf(redMarker('dead1211aa', 3, 3)) !== -1,
